// ControlPlaneServiceServer is the server API for ControlPlaneService service.
// All implementations must embed UnimplementedControlPlaneServiceServer
// for forward compatibility.
//
// ControlPlane is the spine API. Channels feed the event log; the dashboard and CLI drive this.
type ControlPlaneServiceServer interface {
	CreateWorkspace(context.Context, *CreateWorkspaceRequest) (*CreateWorkspaceResponse, error)
	GetWorkspace(context.Context, *GetWorkspaceRequest) (*GetWorkspaceResponse, error)
	ListWorkspaces(context.Context, *ListWorkspacesRequest) (*ListWorkspacesResponse, error)
	DeleteWorkspace(context.Context, *DeleteWorkspaceRequest) (*DeleteWorkspaceResponse, error)
	CreateProject(context.Context, *CreateProjectRequest) (*CreateProjectResponse, error)
	GetProject(context.Context, *GetProjectRequest) (*GetProjectResponse, error)
	ListProjects(context.Context, *ListProjectsRequest) (*ListProjectsResponse, error)
	DeleteProject(context.Context, *DeleteProjectRequest) (*DeleteProjectResponse, error)
	SetDeployTarget(context.Context, *SetDeployTargetRequest) (*SetDeployTargetResponse, error)
	SetProjectRepository(context.Context, *SetProjectRepositoryRequest) (*SetProjectRepositoryResponse, error)
	AttachChannel(context.Context, *AttachChannelRequest) (*AttachChannelResponse, error)
	SetSecret(context.Context, *SetSecretRequest) (*SetSecretResponse, error)
	ListSecrets(context.Context, *ListSecretsRequest) (*ListSecretsResponse, error)
	Dispatch(context.Context, *DispatchRequest) (*DispatchResponse, error)
	OpenDriver(context.Context, *OpenDriverRequest) (*OpenDriverResponse, error)
	ListSessions(context.Context, *ListSessionsRequest) (*ListSessionsResponse, error)
	GetSession(context.Context, *GetSessionRequest) (*GetSessionResponse, error)
	AttachSession(context.Context, *AttachSessionRequest) (*AttachSessionResponse, error)
	StopSession(context.Context, *StopSessionRequest) (*StopSessionResponse, error)
	// StopExec halts the exec a session is running and keeps the session. StopSession above puts the
	// whole session down; this is the one an operator reaches for when an exec is doing the wrong thing.
	StopExec(context.Context, *StopExecRequest) (*StopExecResponse, error)
	// ReclaimSession takes a settled session's container back and keeps everything else. The controller
	// calls it; nothing an operator types does.
	ReclaimSession(context.Context, *ReclaimSessionRequest) (*ReclaimSessionResponse, error)
	DrainSessions(context.Context, *DrainSessionsRequest) (*DrainSessionsResponse, error)
	RestartSession(context.Context, *RestartSessionRequest) (*RestartSessionResponse, error)
	ArchiveSession(context.Context, *ArchiveSessionRequest) (*ArchiveSessionResponse, error)
	RestoreSession(context.Context, *RestoreSessionRequest) (*RestoreSessionResponse, error)
	SetSessionPermissionMode(context.Context, *SetSessionPermissionModeRequest) (*SetSessionPermissionModeResponse, error)
	SetSessionLabel(context.Context, *SetSessionLabelRequest) (*SetSessionLabelResponse, error)
	ListContexts(context.Context, *ListContextsRequest) (*ListContextsResponse, error)
	SetContext(context.Context, *SetContextRequest) (*SetContextResponse, error)
	// What a project is for and what was designed for it. The driver may call the first three: reading
	// what the project holds is the point, and a session that writes a design grants itself nothing.
	GetDesign(context.Context, *GetDesignRequest) (*GetDesignResponse, error)
	SetBrief(context.Context, *SetBriefRequest) (*SetBriefResponse, error)
	SetDesign(context.Context, *SetDesignRequest) (*SetDesignResponse, error)
	// The operator's word on a design, and the driver is refused it. A session that could approve its
	// own design would be agreeing with itself, which is the whole thing this gate exists to stop.
	ApproveDesign(context.Context, *ApproveDesignRequest) (*ApproveDesignResponse, error)
	// The path a design was broken into. The control plane parses the document, so the command line
	// and the console send the same words and cannot drift on the grammar.
	//
	// The driver may call both: a design session is what writes a path, and writing one grants it
	// nothing that dispatching would not.
	SetPath(context.Context, *SetPathRequest) (*SetPathResponse, error)
	ListSteps(context.Context, *ListStepsRequest) (*ListStepsResponse, error)
	// Reads a file, or a listing, out of the work a session left behind, without attaching to it.
	ReadSessionWork(context.Context, *ReadSessionWorkRequest) (*ReadSessionWorkResponse, error)
	// Says where an address is on the machine, so a person can put a file in it by hand. It reads the
	// layout rather than a running container, so it answers when nothing is running.
	LocateDirectory(context.Context, *LocateDirectoryRequest) (*LocateDirectoryResponse, error)
	ImportSkill(context.Context, *ImportSkillRequest) (*ImportSkillResponse, error)
	ListSkills(context.Context, *ListSkillsRequest) (*ListSkillsResponse, error)
	AttachSkill(context.Context, *AttachSkillRequest) (*AttachSkillResponse, error)
	DetachSkill(context.Context, *DetachSkillRequest) (*DetachSkillResponse, error)
	ImportHook(context.Context, *ImportHookRequest) (*ImportHookResponse, error)
	ListHooks(context.Context, *ListHooksRequest) (*ListHooksResponse, error)
	AttachHook(context.Context, *AttachHookRequest) (*AttachHookResponse, error)
	DetachHook(context.Context, *DetachHookRequest) (*DetachHookResponse, error)
	ListExecs(context.Context, *ListExecsRequest) (*ListExecsResponse, error)
	ListSessionEvents(context.Context, *ListSessionEventsRequest) (*ListSessionEventsResponse, error)
	GetInfo(context.Context, *GetInfoRequest) (*GetInfoResponse, error)
	// GetUsage adds up what every conversation in the system has cost. It is a running total rather than
	// configuration, which is why it is not part of GetInfo.
	GetUsage(context.Context, *GetUsageRequest) (*GetUsageResponse, error)
	// GetHealth is the system's last probe of the parts it has to write to before a dispatch can start.
	// It is a verdict, which is why it is not part of GetInfo, and it answers from the last probe for
	// the reason GetHeadroom answers from the last sample.
	GetHealth(context.Context, *GetHealthRequest) (*GetHealthResponse, error)
	mustEmbedUnimplementedControlPlaneServiceServer()
}

